// Wardrobe racks (buy an item: it goes straight on) and fitting rooms (free: open the picker and change into anything you own).
// And the arenas' WEAR-O-MATIC: the picker in shop mode (every item; buy one, or change into one you own).
// The ticket text is generated by game/wardrobe.js from the item's factors and the player's stats right now.
import { wardrobeItems, showpieces, wardrobeMachine } from '../../config/wardrobe.js';
import { createFittingRoomPicker } from './fittingRoomPicker.js';

export function buildWardrobeRack(spot, { map, pricing, interactions, wardrobe, events, sound, player }) {
  const { item: id, zone, position, showpiece } = spot;
  const { name, pa, motif } = wardrobeItems[id];
  interactions.add({
    kind: 'wardrobe',
    id,
    label: name,
    verb: 'buy',
    position,
    get detail() { return wardrobe.ticketDetail(id); },
    get detailLines() { return wardrobe.statLines(id); }, // (which terms are upsides and which downsides: the HUD colours them)
    get cost() { return pricing.priceOf('wardrobe', id); },
    available: () => map.zones[zone].open && !wardrobe.owns(id),
    use: () => {
      const bought = wardrobe.buy(id);
      if (bought && showpiece) { // the buying moment: the showpiece strikes its pose and the mall PA announces it
        showpiece.pose();
        if (pa) events.emit('wardrobeBuy', { id, pa });
      }
      return bought;
    },
  });
  if (!showpiece) return null;

  // A showpiece: sold out once owned (Play again clears it), and its motif hums while you are near and it is unsold.
  let motifIn = 0;
  return {
    update(dt) {
      showpiece.setSold(wardrobe.owns(id));
      showpiece.update(dt);
      if (!motif || wardrobe.owns(id)) return;
      motifIn -= dt;
      if (motifIn > 0 || !map.zones[zone].open) return;
      if (Math.abs(player.position.y - showpiece.root.position.y) > showpieces.motifFloorTolerance) return;
      const away = Math.hypot(player.position.x - position.x, player.position.z - position.z);
      if (away > showpieces.motifRange) return;
      motifIn = showpieces.motifSeconds;
      sound.play(motif, { volume: showpieces.motifVolume * (1 - away / (showpieces.motifRange * 1.5)) });
    },
    reset() {
      motifIn = 0;
      showpiece.reset();
    },
  };
}

export function buildFittingRoom(spot, { map, interactions, wardrobe, input, state, events, sound, player }) {
  const picker = createFittingRoomPicker({ input, state, events, sound, wardrobe, player, position: spot.position });
  interactions.add({
    kind: 'fittingRoom',
    id: 'picker',
    label: 'Fitting room',
    title: 'Change your outfit',
    detail: 'Opens everything you own',
    verb: 'change',
    priceLabel: 'Free',
    cost: 0,
    quiet: true, // (opening the picker isn't a purchase; a confirmed change announces itself)
    position: spot.position,
    available: () => map.zones[spot.zone].open && wardrobe.canChange,
    use: () => picker.open(),
  });
  return {
    picker,
    get view() { return picker.view; },
    update: (dt) => picker.update(dt),
    reset: () => picker.reset(),
  };
}

// The WEAR-O-MATIC (arena survival only: config/arenas.js wardrobeMachine): the fitting-room picker in shop mode, so one machine is
// every rack and a fitting room at once. Opening it is free; it buys at priceOf('wearOMatic', id) (the convenience fee).
export function buildWardrobeMachine(spot, { map, pricing, wallet, interactions, wardrobe, input, state, events, sound, player }) {
  const shop = { pricing, wallet, category: 'wearOMatic', kicker: wardrobeMachine.kicker };
  const picker = createFittingRoomPicker({ input, state, events, sound, wardrobe, player, position: spot.position, shop });
  interactions.add({
    kind: 'wardrobeMachine',
    id: 'picker',
    label: wardrobeMachine.name,
    title: wardrobeMachine.prompt.title,
    detail: wardrobeMachine.prompt.detail,
    verb: wardrobeMachine.prompt.verb,
    priceLabel: wardrobeMachine.prompt.priceLabel,
    cost: 0,
    quiet: true, // (opening it isn't a purchase; a bought or changed item announces itself)
    position: spot.position,
    available: () => map.zones[spot.zone].open,
    use: () => picker.open(),
  });
  return {
    picker,
    get view() { return picker.view; },
    update: (dt) => picker.update(dt),
    reset: () => picker.reset(),
  };
}
